parameters.jsCode:
const e = $input.first().json;

const workflow = e.workflow || {};
const execution = e.execution || {};
const error = execution.error || {};

// Basic workflow information
const workflow_name = workflow.name || 'Unknown';
const workflow_id = workflow.id || 'Unknown';
const execution_id = execution.id || 'Unknown';

// Failed node information
const failed_node =
  execution.lastNodeExecuted ||
  execution.node?.name ||
  'Unknown';

// Error details
const error_message =
  error.message ||
  error.description ||
  'Unknown error';

const error_name =
  error.name ||
  'Unknown';

const error_stack =
  error.stack ||
  '';

// Execution timing
const timestamp = new Date().toISOString();

const execution_mode =
  execution.mode ||
  'Unknown';

// Environment
const environment =
  workflow.active === true
    ? 'Production'
    : 'Development';

return [
  {
    json: {
      workflow_name,
      workflow_id,
      execution_id,
      failed_node,
      error_name,
      error_message,
      error_stack,
      execution_mode,
      environment,
      timestamp
    }
  }
];

